-- READ-ONLY exact-key source-copy comparison; 25 source-present 2019-2020 gap intervals.
WITH gaps AS (SELECT '2019:1558259700:1558341000' gap_id, 1558259700 left_time, 1558341000 right_time UNION ALL SELECT '2019:1559203200:1559208900' gap_id, 1559203200 left_time, 1559208900 right_time UNION ALL SELECT '2019:1559209500:1559213700' gap_id, 1559209500 left_time, 1559213700 right_time UNION ALL SELECT '2019:1559219100:1559223300' gap_id, 1559219100 left_time, 1559223300 right_time UNION ALL SELECT '2019:1572134100:1572138000' gap_id, 1572134100 left_time, 1572138000 right_time UNION ALL SELECT '2020:1582104300:1582122300' gap_id, 1582104300 left_time, 1582122300 right_time UNION ALL SELECT '2020:1582401000:1582404900' gap_id, 1582401000 left_time, 1582404900 right_time UNION ALL SELECT '2020:1582604400:1582613100' gap_id, 1582604400 left_time, 1582613100 right_time UNION ALL SELECT '2020:1582666200:1582680000' gap_id, 1582666200 left_time, 1582680000 right_time UNION ALL SELECT '2020:1583030400:1583038800' gap_id, 1583030400 left_time, 1583038800 right_time UNION ALL SELECT '2020:1583044200:1583069100' gap_id, 1583044200 left_time, 1583069100 right_time UNION ALL SELECT '2020:1583069100:1583089800' gap_id, 1583069100 left_time, 1583089800 right_time UNION ALL SELECT '2020:1583110200:1583117400' gap_id, 1583110200 left_time, 1583117400 right_time UNION ALL SELECT '2020:1583125800:1583140800' gap_id, 1583125800 left_time, 1583140800 right_time UNION ALL SELECT '2020:1583158800:1583166600' gap_id, 1583158800 left_time, 1583166600 right_time UNION ALL SELECT '2020:1589369100:1589372700' gap_id, 1589369100 left_time, 1589372700 right_time UNION ALL SELECT '2020:1589378700:1589384400' gap_id, 1589378700 left_time, 1589384400 right_time UNION ALL SELECT '2020:1589387400:1589402100' gap_id, 1589387400 left_time, 1589402100 right_time UNION ALL SELECT '2020:1589411100:1589414700' gap_id, 1589411100 left_time, 1589414700 right_time UNION ALL SELECT '2020:1590039600:1590063600' gap_id, 1590039600 left_time, 1590063600 right_time UNION ALL SELECT '2020:1590086100:1590090000' gap_id, 1590086100 left_time, 1590090000 right_time UNION ALL SELECT '2020:1592803800:1592827800' gap_id, 1592803800 left_time, 1592827800 right_time UNION ALL SELECT '2020:1592890500:1592915400' gap_id, 1592890500 left_time, 1592915400 right_time UNION ALL SELECT '2020:1593612000:1593617100' gap_id, 1593612000 left_time, 1593617100 right_time UNION ALL SELECT '2020:1595488200:1595493000' gap_id, 1595488200 left_time, 1595493000 right_time)
SELECT g.gap_id, COUNT(o.dateTime) old_rows, COUNT(w.dateTime) same_timestamp_rows, SUM(w.dateTime IS NULL) old_timestamp_without_wh, SUM(o.outTemp IS NOT NULL AND w.outTemp IS NOT NULL) outTemp_paired_nonnull, SUM(o.outTemp IS NOT NULL AND w.outTemp IS NOT NULL AND o.outTemp=w.outTemp) outTemp_exact_raw_match, SUM(o.outTemp IS NOT NULL AND w.outTemp IS NOT NULL AND o.outTemp<>w.outTemp) outTemp_raw_mismatch, SUM(o.outHumidity IS NOT NULL AND w.outHumidity IS NOT NULL) outHumidity_paired_nonnull, SUM(o.outHumidity IS NOT NULL AND w.outHumidity IS NOT NULL AND o.outHumidity=w.outHumidity) outHumidity_exact_raw_match, SUM(o.outHumidity IS NOT NULL AND w.outHumidity IS NOT NULL AND o.outHumidity<>w.outHumidity) outHumidity_raw_mismatch, SUM(o.rain IS NOT NULL AND w.rain IS NOT NULL) rain_paired_nonnull, SUM(o.rain IS NOT NULL AND w.rain IS NOT NULL AND o.rain=w.rain) rain_exact_raw_match, SUM(o.rain IS NOT NULL AND w.rain IS NOT NULL AND o.rain<>w.rain) rain_raw_mismatch, SUM(o.rainRate IS NOT NULL AND w.rainRate IS NOT NULL) rainRate_paired_nonnull, SUM(o.rainRate IS NOT NULL AND w.rainRate IS NOT NULL AND o.rainRate=w.rainRate) rainRate_exact_raw_match, SUM(o.rainRate IS NOT NULL AND w.rainRate IS NOT NULL AND o.rainRate<>w.rainRate) rainRate_raw_mismatch, SUM(o.windSpeed IS NOT NULL AND w.windSpeed IS NOT NULL) windSpeed_paired_nonnull, SUM(o.windSpeed IS NOT NULL AND w.windSpeed IS NOT NULL AND o.windSpeed=w.windSpeed) windSpeed_exact_raw_match, SUM(o.windSpeed IS NOT NULL AND w.windSpeed IS NOT NULL AND o.windSpeed<>w.windSpeed) windSpeed_raw_mismatch, SUM(o.windGust IS NOT NULL AND w.windGust IS NOT NULL) windGust_paired_nonnull, SUM(o.windGust IS NOT NULL AND w.windGust IS NOT NULL AND o.windGust=w.windGust) windGust_exact_raw_match, SUM(o.windGust IS NOT NULL AND w.windGust IS NOT NULL AND o.windGust<>w.windGust) windGust_raw_mismatch, SUM(o.windDir IS NOT NULL AND w.windDir IS NOT NULL) windDir_paired_nonnull, SUM(o.windDir IS NOT NULL AND w.windDir IS NOT NULL AND o.windDir=w.windDir) windDir_exact_raw_match, SUM(o.windDir IS NOT NULL AND w.windDir IS NOT NULL AND o.windDir<>w.windDir) windDir_raw_mismatch, SUM(o.barometer IS NOT NULL AND w.barometer IS NOT NULL) barometer_paired_nonnull, SUM(o.barometer IS NOT NULL AND w.barometer IS NOT NULL AND o.barometer=w.barometer) barometer_exact_raw_match, SUM(o.barometer IS NOT NULL AND w.barometer IS NOT NULL AND o.barometer<>w.barometer) barometer_raw_mismatch, COUNT(DISTINCT o.usUnits) old_usUnits, COUNT(DISTINCT w.usUnits) wh_usUnits, COUNT(DISTINCT o.`interval`) old_intervals, COUNT(DISTINCT w.`interval`) wh_intervals
FROM gaps g LEFT JOIN `old_weewx`.archive o ON o.dateTime>g.left_time AND o.dateTime<g.right_time LEFT JOIN `weewx_WH1080`.archive w ON w.dateTime=o.dateTime
GROUP BY g.gap_id ORDER BY g.left_time;
